INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('1d44fd32-45eb-531d-a292-9b70a72d8918','88cdfd6a-521f-5a8e-8bce-94f8520b2f86','The verb ''to be''',0,'LESSON',70,$j$[{"type": "rule", "text": "The verb 'to be': I am, you are, he/she/it is, we/you/they are. Short forms: I'm, you're, he's, she's, it's, we're, they're. Negatives: isn't, aren't, I'm not."}, {"type": "examples", "items": ["Is she your sister? No, she isn't. She's my mummy!", "Are they robots? Yes, they are. - No, they aren't."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c3b70ba8-a0b6-5ab9-bb71-02c996c8b924','1d44fd32-45eb-531d-a292-9b70a72d8918',0,'FILL_BLANK','Прочитай и дополни правильной формой глагола ''to be'': am, is или are.',$j${"items": [{"before": "He", "after": "my brother."}, {"before": "They", "after": "friends."}, {"before": "You", "after": "funny!"}, {"before": "She", "after": "my sister."}, {"before": "It", "after": "blue."}, {"before": "We", "after": "here."}, {"before": "It", "after": "a book."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('c3b70ba8-a0b6-5ab9-bb71-02c996c8b924',$j${"items": [{"accept": ["is"]}, {"accept": ["are"]}, {"accept": ["are"]}, {"accept": ["is"]}, {"accept": ["is"]}, {"accept": ["are"]}, {"accept": ["is"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c63235e5-603f-57cf-b66e-2c31b42cb568','1d44fd32-45eb-531d-a292-9b70a72d8918',1,'FILL_BLANK','Посмотри на картинку, ответь и запиши короткую форму (He''s, She''s, It''s, They''re).',$j${"items": [{"before": "Where's Karen and Jen?", "after": "in the living room."}, {"before": "Where's the dog?", "after": "in the garden."}, {"before": "Where's Ben?", "after": "in the kitchen."}]}$j$::jsonb,10);
