INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b075a1a7-d56c-552d-96b4-3ab1d4118888','4f98ad50-adc8-5372-9056-08d240476d33','Possessives',0,'LESSON',70,$j$[{"type": "rule", "text": "We use possessive adjectives (my, your, his, her, its, our, your, their) before nouns to show that something belongs to somebody."}, {"type": "rule", "text": "We use the possessive case ('s) to show that something belongs to somebody: It's Paul's hat."}, {"type": "examples", "items": ["Hello! My name's Tony. This is my brother and his cat, Lucy.", "This isn't my hat. It's Paul's hat."]}]$j$::jsonb);
