INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c84988f2-7167-5cb6-a43e-503da0ad6114','f2babd7a-7650-5806-98e1-00812a2011ae','Plural form II',0,'LESSON',70,$j$[{"type": "rule", "text": "Most nouns: add -s. one carrot – two carrots."}, {"type": "rule", "text": "Nouns ending in -s, -ss, -ch, -x, -o: add -es. one fox – two foxes."}, {"type": "rule", "text": "Consonant + -y: change -y to -ies. one butterfly – two butterflies. Vowel (a, e, o, u) + -y: add -s."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('0a508264-8c45-5082-a3bb-aece1fa783d7','c84988f2-7167-5cb6-a43e-503da0ad6114',0,'FILL_BLANK','Напиши форму множественного числа.',$j${"items": [{"before": "one glass – two", "after": ""}, {"before": "one sandwich – two", "after": ""}, {"before": "one dress – two", "after": ""}, {"before": "one cake – two", "after": ""}, {"before": "one potato – two", "after": ""}, {"before": "one tomato – two", "after": ""}, {"before": "one monkey – two", "after": ""}, {"before": "one butterfly – two", "after": ""}, {"before": "one guitar – two", "after": ""}, {"before": "one clock – two", "after": ""}, {"before": "one puppy – two", "after": ""}]}$j$::jsonb,10);
