INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('876a0693-4a26-5396-ae0a-5f21ec48ecb4','a0000000-0000-4000-8000-0000000000f2','Блок 24. Present Simple',24,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('baa5f193-329d-5565-9ac4-919347501f37','876a0693-4a26-5396-ae0a-5f21ec48ecb4','Present Simple',0,'LESSON',70,$j$[{"type": "rule", "text": "Affirmative: subject + verb. Add -s to the third person singular (he, she, it). e.g. I like – he likes."}, {"type": "rule", "text": "Negative: subject + don't/doesn't + verb. Use doesn't with he, she and it. e.g. I don't like sweets. – He doesn't like sweets."}, {"type": "rule", "text": "Interrogative: Do/Does + subject + verb. Do not add -s to the verb with does/doesn't. e.g. Do you like sweets? – Does he like sweets?"}, {"type": "examples", "items": ["Do you like chocolate? – Yes, I/we do. / No, I/we don't.", "Does he/she/it like chocolate? – Yes, he/she/it does. / No, he/she/it doesn't.", "Do they like chocolate? – Yes, they do. / No, they don't."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f657e497-8bbb-5575-9021-abfe44f09810','baa5f193-329d-5565-9ac4-919347501f37',0,'FILL_BLANK','Напиши глагол в форме третьего лица единственного числа (he).',$j${"items": [{"before": "I listen – he", "after": ""}, {"before": "I sing – he", "after": ""}, {"before": "I draw – he", "after": ""}, {"before": "I read – he", "after": ""}, {"before": "I make – he", "after": ""}, {"before": "I play – he", "after": ""}, {"before": "I dance – he", "after": ""}, {"before": "I ride – he", "after": ""}, {"before": "I swim – he", "after": ""}, {"before": "I run – he", "after": ""}, {"before": "I jump – he", "after": ""}]}$j$::jsonb,10);
