INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('1e2babae-d1d3-501c-bd48-33563b7763b0','baa5f193-329d-5565-9ac4-919347501f37',1,'FILL_BLANK','Дополни отрицательные предложения (полная и краткая формы).',$j${"items": [{"before": "He", "after": "play football. (полная форма)"}, {"before": "He", "after": "play football. (краткая форма)"}, {"before": "She", "after": "ride a bike. (полная форма)"}, {"before": "She", "after": "ride a bike. (краткая форма)"}, {"before": "I", "after": "play the piano. (полная форма)"}, {"before": "I", "after": "play the piano. (краткая форма)"}, {"before": "They", "after": "listen to me! (полная форма)"}, {"before": "They", "after": "listen to me! (краткая форма)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('1e2babae-d1d3-501c-bd48-33563b7763b0',$j${"items": [{"accept": ["does not"]}, {"accept": ["doesn't"]}, {"accept": ["does not"]}, {"accept": ["doesn't"]}, {"accept": ["do not"]}, {"accept": ["don't"]}, {"accept": ["do not"]}, {"accept": ["don't"]}]}$j$::jsonb,'');
