INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('61120134-3c50-5528-9743-3bfe3f711cd4','baa5f193-329d-5565-9ac4-919347501f37',3,'FILL_BLANK','Дополни вопросы (Do/Does) и краткие ответы.',$j${"items": [{"before": "", "after": "you like carrots?"}, {"before": "No, I", "after": "."}, {"before": "", "after": "your friend like lollipops?"}, {"before": "Yes, he", "after": "."}, {"before": "", "after": "your friends like apple juice?"}, {"before": "Yes, they", "after": "."}, {"before": "", "after": "Kelly like oranges?"}, {"before": "No, she", "after": "."}, {"before": "", "after": "your daddy like tomatoes?"}, {"before": "Yes, he", "after": "."}]}$j$::jsonb,10);
