INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('6cf72495-ad98-59ef-943f-ac9d2cfb1315','a0000000-0000-4000-8000-0000000000f2','Блок 25. Present Continuous',25,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('4be71613-decd-57ee-b45a-092035793bbe','6cf72495-ad98-59ef-943f-ac9d2cfb1315','Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the Present Continuous for actions happening now, at the time of speaking. e.g. I am wearing my jeans."}, {"type": "rule", "text": "Affirmative: subject + am/is/are + verb + -ing. e.g. I am wearing my cap."}, {"type": "rule", "text": "Negative: put not after am/is/are. e.g. She is not wearing her new shoes."}, {"type": "rule", "text": "Interrogative: Am/Is/Are + subject + verb-ing. e.g. Are you wearing your jacket?"}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ea0b6607-772c-5328-af5a-997f7ee59891','4be71613-decd-57ee-b45a-092035793bbe',0,'FILL_BLANK','Напиши форму глагола с окончанием -ing.',$j${"items": [{"before": "play –", "after": ""}, {"before": "listen –", "after": ""}, {"before": "look –", "after": ""}, {"before": "draw –", "after": ""}, {"before": "rain –", "after": ""}, {"before": "snow –", "after": ""}, {"before": "jump –", "after": ""}, {"before": "fly –", "after": ""}, {"before": "read –", "after": ""}]}$j$::jsonb,10);
