INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('16079da6-3de9-5682-a187-396c93db8b11','a0000000-0000-4000-8000-0000000000f2','Блок 26. Who - What - Where',26,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('176f2cc5-f80b-5ff8-896c-c2ed5f5bbe90','16079da6-3de9-5682-a187-396c93db8b11','Who - What - Where',0,'LESSON',70,$j$[{"type": "rule", "text": "We use who to ask about people."}, {"type": "rule", "text": "We use what to ask about things."}, {"type": "rule", "text": "We use where to ask about places (where someone or something is)."}, {"type": "examples", "items": ["What's this? - My new bike.", "Who's this? - My brother, Bill.", "Where is he? - In the bedroom."]}]$j$::jsonb);
